"""Content of GRAVITY (Markdown + LaTeX): gravity on the 7+1 spacetime, the Einstein and Lovelock tensors, the generalized
frame matrices, the canonical spin connection and the total covariant derivative, the covariant Dirac equation of
dirac16complex, and the three cosmological epochs (sections 11-14 of 7+1.nb).  Every equation used is written here."""
from docgen import Doc
from doc_stage3_common import fmt, mnum, mlist, break_sum
from doc_common import signature_block

def build(D, today):
    ck = D['checks']['grav']; ref = D['ref'].get('grav', ('', '', {}))[2]; nm = D['nums']['grav']
    nck = len(ck); nok = sum(1 for c in ck if c[1] == 'True')
    nref = sum(1 for k, v in ref.items() if v in ('True', 'False')); nrefok = sum(1 for k, v in ref.items() if v == 'True')
    d = Doc('Gravity on the 7+1 spacetime and the coupling of dirac16complex to it',
            'Einstein and Lovelock tensors, generalized frame matrices, the canonical spin connection with a vanishing total covariant '
            'derivative, the covariant Dirac equation of dirac16complex, and the primordial, modern and far-future epochs — sections '
            '11–14 of the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1), evaluated ' + D['log'].get('finished', ''),
             'Document generated by tools/make_docs.py on ' + today],
            'This document puts the 16-component field dirac16complex of the 7+1 project into a gravitational field. The spacetime has '
            'ONE time coordinate $x_0$ and SEVEN space coordinates $x_1,\\dots,x_7$; the four auxiliary space-like coordinates '
            '$x_4,\\dots,x_7$ may expand or contract at their own rate. It defines and checks the curvature of a general metric, the '
            'Lovelock tensors of 7+1 spacetime (Einstein, Gauss–Bonnet, cubic; the quartic one vanishes identically in eight dimensions) '
            'and the Einstein–Lovelock field equations; the generalized frame matrices $\\Gamma_\\mu(X)=e^A{}_\\mu(X)\\,\\Gamma_A$ built from '
            'the real 16×16 Dirac matrices; the canonical spin connection, for which the total covariant derivative of every frame matrix '
            'vanishes; the covariant Dirac equation, in which that spin connection couples gravity to dirac16complex; and the three '
            'cosmological epochs — primordial (near $x_0=0$), modern, far future — with the creation of dirac16complex pairs in each. '
            'The ideas follow the repository Dirac_claude, rebuilt for 7+1: Dirac_claude uses a 4+4 spacetime with four time-like '
            'coordinates and a warped metric, none of which is used here. Sections 11–14 of 7+1.nb contain %d checks (%d True); the '
            'independent Python program tools/ref_gravity.py contains %d (%d True).' % (nck, nok, nref, nrefok))

    # ==============================================================================================
    d.h1('1. Results at a glance')
    d.p('**Spacetime.** Coordinates $X=(x_0,x_1,\\dots,x_7)$ with $x_0$ the time (the direction of the octonion unit $e_0=1$), '
        '$x_1,x_2,x_3$ ordinary space and $x_4,\\dots,x_7$ auxiliary space: one time-like and seven space-like dimensions, which xAct '
        'declares, as the reference notebook Einstein-Lovelock-7+1-Nash.nb does, with the signature list $\\{7,1,0\\}$ (seven space-like, '
        'one time-like, none degenerate). The frame metric — simply the squares of the octonion basis, $e_0^2=+1$, $e_i^2=-1$ '
        '(section 2) — and the eight real Dirac matrices are')
    d.eq(r'\eta=\mathrm{diag}(+1,-1,\dots,-1),\qquad \Gamma_0=\begin{pmatrix}0&1_8\\1_8&0\end{pmatrix},\quad '
         r'\Gamma_i=\begin{pmatrix}\tau^{O}_i&0\\0&-\tau^{O}_i\end{pmatrix},\qquad \Gamma_A\Gamma_B+\Gamma_B\Gamma_A=2\eta_{AB}1_{16},')
    d.p('with the real antisymmetric 8×8 octonion matrices $\\tau^{O}_i$ ($i=1,\\dots,7$, $(\\tau^O_i)^2=-1_8$, mutually anticommuting).')
    d.p('**Lovelock tensors** of order $k$, with the generalized Kronecker delta $\\delta^{\\mu_1\\cdots\\mu_n}_{\\nu_1\\cdots\\nu_n}=\\det[\\delta^{\\mu_i}_{\\nu_j}]$:')
    d.eq(r'E^{(k)\mu}{}_{\nu}=-\frac{1}{2^{k+1}}\,\delta^{\mu\alpha_1\beta_1\cdots\alpha_k\beta_k}_{\nu\gamma_1\delta_1\cdots\gamma_k\delta_k}\,'
         r'R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}\cdots R^{\gamma_k\delta_k}{}_{\alpha_k\beta_k},\\ '
         r'E^{(0)}=-\tfrac12\,\delta,\quad E^{(1)}=G\ \text{(Einstein)},\quad E^{(4)}\equiv0\ \text{in }D=8.')
    d.p('**Einstein–Lovelock field equations** ($\\alpha_0=2\\Lambda$, $\\alpha_1=1$, $\\kappa=8\\pi G_8$):')
    d.eq(r'\sum_{k=0}^{3}\alpha_k\,E^{(k)\mu}{}_{\nu}=\kappa\,T^{\mu}{}_{\nu}.')
    d.p('**Generalized frame matrices, canonical spin connection, total covariant derivative:**')
    d.align([r'\Gamma_\mu(X)&=e^A{}_\mu(X)\,\Gamma_A,\qquad \Gamma_\mu\Gamma_\nu+\Gamma_\nu\Gamma_\mu=2g_{\mu\nu}(X)\,1_{16},',
             r'\omega_\mu{}^A{}_B&=e^A{}_\nu\big(\partial_\mu e_B{}^\nu+\{{}^{\nu}_{\mu\lambda}\}\,e_B{}^\lambda\big),\qquad '
             r'\Omega_\mu=\tfrac14\,\omega_{\mu AB}\,\Gamma^A\Gamma^B,',
             r'\nabla_\mu\Gamma_\nu&=\partial_\mu\Gamma_\nu-\{{}^{\lambda}_{\mu\nu}\}\Gamma_\lambda+[\Omega_\mu,\Gamma_\nu]=0 .'])
    d.p('**Covariant Dirac equation of dirac16complex** ($D_\\mu=\\partial_\\mu+\\Omega_\\mu$, $\\bar\\psi=\\psi^\\dagger\\Gamma_0$):')
    d.eq(r'\big(i\,\Gamma^\mu(X)\,D_\mu-m\big)\psi=0,\qquad (\Gamma^\mu D_\mu)^2=g^{\mu\nu}\nabla_\mu D_\nu-\tfrac{R}{4}\,1_{16}.')
    d.p('**Three epochs** of the cosmological metric $ds^2=dx_0^2-a^2(dx_1^2+dx_2^2+dx_3^2)-b^2(dx_4^2+\\cdots+dx_7^2)$: '
        'primordial Kasner solutions near $x_0=0$ (Einstein: $a=x_0^{p}$, $b=x_0^{q}$ with $p=(1\\pm2\\sqrt2)/7$, $q=(2\\mp3\\sqrt2)/14$; '
        'Gauss–Bonnet and cubic Lovelock exponents below), a modern epoch with a static auxiliary space ($b=b_0$, ordinary '
        'Friedmann cosmology with $G_4=G_8/V_\\perp$), and de Sitter far futures, in which dirac16complex pairs are created with the '
        'Fermi–Dirac distribution at the Gibbons–Hawking temperature, $|\\beta|^2=1/(e^{2\\pi M/H}+1)$.')

    # ==============================================================================================
    d.h1('2. Conventions')
    d.ul(['Units: $\\hbar=c=1$. A prime is $d/dx_0$.',
          'Indices: Greek $\\mu,\\nu,\\lambda,\\rho,\\sigma,\\alpha,\\beta,\\gamma,\\delta\\in\\lbrace0,\\dots,7\\rbrace$ are coordinate indices; '
          'Latin capitals $A,B,C\\in\\lbrace0,\\dots,7\\rbrace$ are frame indices, raised and lowered with $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$, '
          'the squares of the octonion basis ($\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$); repeated indices are summed. '
          'In Mathematica all lists are 1-based: $g_{\\mu\\nu}$ is `g[[μ+1, ν+1]]`.',
          'Signature: one time-like dimension ($x_0$, with $g_{00}>0$) and seven space-like dimensions ($x_1,\\dots,x_7$, negative squares); '
          'in xAct the signature $\\{7,1,0\\}$ (seven space-like, one time-like, none degenerate), as in the reference notebook.',
          'Christoffel symbols are written $\\{{}^{\\lambda}_{\\mu\\nu}\\}$ — never $\\Gamma$, which in this project always denotes a Dirac matrix:',
          ])
    d.eq(r'\{{}^{\lambda}_{\mu\nu}\}=\tfrac12\,g^{\lambda\rho}\big(\partial_\mu g_{\rho\nu}+\partial_\nu g_{\rho\mu}-\partial_\rho g_{\mu\nu}\big).')
    d.p('Curvature (the convention of Landau and Lifshitz):')
    d.align([r'R^{\rho}{}_{\sigma\mu\nu}&=\partial_\mu\{{}^{\rho}_{\sigma\nu}\}-\partial_\nu\{{}^{\rho}_{\sigma\mu}\}'
             r'+\{{}^{\rho}_{\mu\lambda}\}\{{}^{\lambda}_{\sigma\nu}\}-\{{}^{\rho}_{\nu\lambda}\}\{{}^{\lambda}_{\sigma\mu}\},',
             r'R_{\sigma\nu}&=R^{\rho}{}_{\sigma\rho\nu},\qquad R=g^{\sigma\nu}R_{\sigma\nu},\qquad G^{\mu}{}_{\nu}=R^{\mu}{}_{\nu}-\tfrac12\delta^\mu_\nu R,'
             r'\qquad R^{\gamma\delta}{}_{\alpha\beta}=g^{\delta\sigma}R^{\gamma}{}_{\sigma\alpha\beta}.'])
    d.p('With these conventions and the signs of $\\eta$ ($g_{00}>0$) the field equations of general relativity read '
        '$G^\\mu{}_\\nu-\\Lambda\\delta^\\mu_\\nu=\\kappa T^\\mu{}_\\nu$ with $T^0{}_0>0$ the energy density, and a de Sitter space has '
        '$R<0$.')
    signature_block(d, eta=r'\eta', eta71=r'\eta_{71}', gam=r'\Gamma')

    # ==============================================================================================
    d.h1('3. Curvature of a 7+1 metric (section 11 of 7+1.nb)')
    d.p('The notebook function `curvature[g, simp]` returns, for an 8×8 metric in the coordinates $X$, the inverse metric, the '
        'Christoffel symbols, $R^\\rho{}_{\\sigma\\mu\\nu}$, $R^{\\gamma\\delta}{}_{\\alpha\\beta}$, the Ricci tensor, $R$ and $G^\\mu{}_\\nu$. '
        'Three test metrics are used throughout:')
    d.ol(['the **cosmological metric** $g=\\mathrm{diag}(1,-a^2,-a^2,-a^2,-b^2,-b^2,-b^2,-b^2)$ with arbitrary $a(x_0)$ (`a3[x0]`) and '
          '$b(x_0)$ (`b4[x0]`);',
          'an **inhomogeneous metric** $g=\\mathrm{diag}(n^2,-a^2,-a^2,-a^2,-b^2,-b^2,-b^2,-b^2)$ in which $n,a,b$ are explicit polynomials '
          'of BOTH $x_0$ and $x_4$: $n=1+x_0x_4/5+x_0^2/11$, $a=1+x_0/3+x_4^2/7$, $b=2-x_0x_4/4+x_0^2/9+x_4/13$ (`nP`, `aP`, `bP`); its '
          'identities are checked exactly (rational numbers) at the point $x_0=1/2$, $x_4=1/3$;',
          'a **plane gravitational wave** (pp-wave) $ds^2=dx_0^2-dx_1^2-\\cdots-dx_7^2+F(x_0-x_1,x_2,x_3)\\,(dx_0-dx_1)^2$ with an '
          'arbitrary profile $F$ (`fPP`), which is not diagonal.'])
    d.p('For the cosmological metric, with the Hubble rates $H_a=a\'/a$ and $H_b=b\'/b$, the Riemann tensor in the orthonormal frame is '
        'diagonal on index pairs; its only components are the sectional curvatures $K_{AB}=R^{AB}{}_{AB}$ (no sum), with $i,j\\in\\lbrace1,2,3\\rbrace$, $k,l\\in\\lbrace4,\\dots,7\\rbrace$:')
    d.eq(r"K_{0i}=-(H_a'+H_a^2),\quad K_{0k}=-(H_b'+H_b^2),\quad K_{ij}=-H_a^2,\quad K_{kl}=-H_b^2,\quad K_{ik}=-H_aH_b .")
    d.p('The Einstein tensor and the scalar curvature are')
    d.align([r"G^0{}_0&=3H_a^2+12H_aH_b+6H_b^2,",
             r"G^1{}_1=G^2{}_2=G^3{}_3&=2H_a'+3H_a^2+4H_b'+10H_b^2+8H_aH_b,",
             r"G^4{}_4=\cdots=G^7{}_7&=3H_a'+6H_a^2+3H_b'+6H_b^2+9H_aH_b,",
             r"R&=-2\big(3H_a'+6H_a^2+4H_b'+10H_b^2+12H_aH_b\big)."])
    d.p('For the inhomogeneous metric the notebook checks, exactly at $x_0=1/2$, $x_4=1/3$, the symmetries of the Riemann tensor '
        '($R_{\\rho\\sigma\\mu\\nu}=-R_{\\sigma\\rho\\mu\\nu}=-R_{\\rho\\sigma\\nu\\mu}=R_{\\mu\\nu\\rho\\sigma}$ with $R_{\\rho\\sigma\\mu\\nu}=g_{\\rho\\lambda}R^\\lambda{}_{\\sigma\\mu\\nu}$), the first '
        'Bianchi identity $R^\\rho{}_{\\sigma\\mu\\nu}+R^\\rho{}_{\\mu\\nu\\sigma}+R^\\rho{}_{\\nu\\sigma\\mu}=0$, and the contracted Bianchi identity')
    d.eq(r'\nabla_\mu G^{\mu}{}_{\nu}=\partial_\mu G^\mu{}_\nu+\{{}^{\mu}_{\mu\lambda}\}G^\lambda{}_\nu-\{{}^{\lambda}_{\mu\nu}\}G^\mu{}_\lambda=0 .')
    d.p('(the contracted Bianchi identity is also checked for the cosmological metric with arbitrary $a(x_0)$, $b(x_0)$). A fourth '
        'metric enters in section 5.4: the static metric $ds^2=f(r)\\,dx_0^2-h(r)\\,dr^2-r^2(dx_2^2+\\cdots+dx_7^2)$ with $r=x_1$ and arbitrary '
        'positive $f$, $h$.')

    # ==============================================================================================
    d.h1('4. The Lovelock tensors of 7+1 spacetime (section 12)')
    d.h2('4.1 Lovelock’s theorem and the definitions')
    d.p('In $n$ dimensions the most general tensor $A^{lh}$ that is symmetric, divergence-free and built from the metric and its first '
        'and second derivatives is (D. Lovelock and H. Rund, *Tensors, Differential Forms, and Variational Principles*, Dover; Remark 2 '
        'after their Eq. (4.38))')
    d.eq(r'A^{lh}=\sqrt{|g|}\sum_{k=1}^{m-1}\alpha_{(k)}\,g^{jl}\,\delta^{h h_1\cdots h_{2k}}_{j j_1\cdots j_{2k}}\,'
         r'R^{j_1j_2}{}_{h_1h_2}\cdots R^{j_{2k-1}j_{2k}}{}_{h_{2k-1}h_{2k}}+\lambda\sqrt{|g|}\,g^{lh},\qquad '
         r'm=\begin{cases}n/2,&n\ \text{even},\\(n+1)/2,&n\ \text{odd},\end{cases}')
    d.p('with arbitrary constants $\\alpha_{(k)}$ and $\\lambda$. For $n=8$, $m-1=8/2-1=3$: there are exactly three curvature terms. '
        'The generalized Kronecker delta is the determinant of the matrix of ordinary Kronecker deltas,')
    d.eq(r'\delta^{\mu_1\cdots\mu_n}_{\nu_1\cdots\nu_n}=\det\big[\delta^{\mu_i}_{\nu_j}\big]_{i,j=1}^{n},\qquad '
         r'\delta^{\mu_1\cdots\mu_p\rho}_{\nu_1\cdots\nu_p\rho}=(8-p)\,\delta^{\mu_1\cdots\mu_p}_{\nu_1\cdots\nu_p}\ \ (D=8),')
    d.p('it is $+1$ ($-1$) when the lower indices are an even (odd) permutation of the upper ones, all different, and $0$ otherwise; it '
        'vanishes when $n>8$. With the normalization of the reference notebook Einstein-Lovelock-7+1-Nash.nb (P. L. Nash, GPL), which this '
        'document follows, the Lovelock tensors (`Lovelock1`, `Lovelock2`, `Lovelock3`) and densities are')
    d.align([r'\mathrm{Lovelock}_k\equiv E^{(k)\mu}{}_{\nu}&=-\frac{1}{2^{k+1}}\,\delta^{\mu\alpha_1\beta_1\cdots\alpha_k\beta_k}_{\nu\gamma_1\delta_1\cdots\gamma_k\delta_k}\,'
             r'R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}\cdots R^{\gamma_k\delta_k}{}_{\alpha_k\beta_k},',
             r'L_k&=\frac{1}{2^k}\,\delta^{\alpha_1\beta_1\cdots\alpha_k\beta_k}_{\gamma_1\delta_1\cdots\gamma_k\delta_k}\,'
             r'R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}\cdots R^{\gamma_k\delta_k}{}_{\alpha_k\beta_k}.'])
    d.p('Special cases: $L_0=1$, $E^{(0)\\mu}{}_\\nu=-\\tfrac12\\delta^\\mu_\\nu$; $L_1=R$, $E^{(1)}=G$; $L_2=R^2-4R_{\\mu\\nu}R^{\\mu\\nu}+'
        'R_{\\mu\\nu\\rho\\sigma}R^{\\mu\\nu\\rho\\sigma}$ (Gauss–Bonnet) with $E^{(2)}$ the Lanczos tensor')
    d.eq(r'E^{(2)}_{\mu\nu}=2\big(R\,R_{\mu\nu}-2R_{\mu\alpha}R^{\alpha}{}_{\nu}-2R^{\alpha\beta}R_{\mu\alpha\nu\beta}'
         r'+R_{\mu}{}^{\alpha\beta\gamma}R_{\nu\alpha\beta\gamma}\big)-\tfrac12 g_{\mu\nu}L_2 ;')
    d.p('$L_3$, $E^{(3)}$ are cubic in the curvature (section 4.3 gives $E^{(3)}$ explicitly). Because $E^{(k)}$ contains $2k+1$ '
        'different upper indices, $E^{(4)}\\equiv0$ in eight dimensions, although $L_4$ (the Euler density) is not zero; $\\sqrt{|g|}L_4$ '
        'is a total derivative. Every $E^{(k)}$ is symmetric with both indices down, divergence-free for every metric, and has the trace')
    d.eq(r'E^{(k)\mu}{}_{\mu}=-\frac{8-2k}{2}\,L_k .')
    d.h2('4.2 Action and field equations')
    d.p('The reference notebook writes the Einstein–Lovelock VACUUM field equations as')
    d.eq(r'0=-\Lambda\,\delta^\mu_\nu+H^{-2}\,w_1\,\mathrm{Lovelock}_1+H^{-4}\,w_2\,\mathrm{Lovelock}_2+H^{-6}\,w_3\,\mathrm{Lovelock}_3,')
    d.p('with pure numbers $w_1,w_2,w_3,\\Lambda$ and a fundamental inverse length $H$ (it exists because the Lovelock tensors of '
        'different orders have different dimensions, length$^{-2k}$). With matter, and with $\\delta(\\sqrt{|g|}L_k)=\\sqrt{|g|}\\,'
        'E^{(k)}_{\\mu\\nu}\\,\\delta g^{\\mu\\nu}$ (up to a total derivative) and $\\delta S_{\\text{matter}}=\\tfrac12\\int\\sqrt{|g|}\\,T_{\\mu\\nu}'
        '\\,\\delta g^{\\mu\\nu}\\,d^8X$, the action')
    d.eq(r'S=-\frac{1}{2\kappa}\int d^8X\,\sqrt{|g|}\,\sum_{k=0}^{3}\alpha_k L_k+S_{\text{matter}},\qquad \alpha_0=2\bar\Lambda,\ \ \alpha_1=1,')
    d.p('gives the Einstein–Lovelock field equations')
    d.eq(r'\sum_{k=0}^{3}\alpha_k\,E^{(k)\mu}{}_{\nu}=\kappa\,T^\mu{}_\nu\qquad\Longleftrightarrow\qquad '
         r'G^\mu{}_\nu+\alpha_2E^{(2)\mu}{}_\nu+\alpha_3E^{(3)\mu}{}_\nu-\bar\Lambda\,\delta^\mu_\nu=\kappa\,T^\mu{}_\nu,')
    d.p('with $\\kappa=8\\pi G_8$ ($G_8$ the Newton constant of eight dimensions), the Gauss–Bonnet and cubic couplings $\\alpha_2$, '
        '$\\alpha_3$ (dimensions length² and length⁴) and the cosmological constant $\\bar\\Lambda$ (dimension length$^{-2}$; it is '
        'written $\\Lambda$ in sections 7 and following, where no pure number $\\Lambda$ appears). $\\alpha_4$ does not appear: its tensor '
        'vanishes. For $T=0$ the two forms are the same equation (divide the first by $w_1/H^2$):')
    d.eq(r'\alpha_2=\frac{w_2}{w_1H^2},\qquad \alpha_3=\frac{w_3}{w_1H^4},\qquad \bar\Lambda=\frac{\Lambda H^2}{w_1}.')

    d.h2('4.3 The Lovelock tensors with xAct, as in the reference notebook')
    d.p('Section 12 of 7+1.nb computes the Lovelock tensors exactly as the reference notebook does, with the tensor packages xAct '
        '(xPerm, xTensor, xCoba, xTras; J. M. Martín-García et al., GPL; versions %s). The reference notebook also contains a "Model metric" '
        'which its author has marked FAILED, DO NOT USE (it never worked for the 7+1 signature); it is not used anywhere in this project. '
        'The set-up (abstract indices $a$, $b$, $c$, $d$, $f$, $i$, $j$, $k$, $l$, $m$, $n$, $p$, $q$, $r$, $s$, $y$; a metric `g71` with Levi-Civita derivative `CD`; a chart '
        '`chartM8` with the coordinate scalars `x0[]`, …, `x7[]`):' % (D.get('xact_versions') or 'as printed in section 12.2 of 7+1.nb'))
    d.code('Needs["xAct`xCoba`"]; Needs["xAct`xTras`"];\n'
           '$DefInfoQ = False; $CVVerbose = False;\n'
           'SetOptions[ToCanonical, UseMetricOnVBundle -> None, Verbose -> False];\n'
           'DefManifold[M8, 8, {a, b, c, d, f, i, j, k, l, m, n, p, q, r, s, y}];\n'
           'DefMetric[{7, 1, 0}, g71[-a, -b], CD, {";", "D"}, WeightedWithBasis -> AIndex];\n'
           'DefChart[chartM8, M8, {0, 1, 2, 3, 4, 5, 6, 7}, {x0[], x1[], x2[], x3[], x4[], x5[], x6[], x7[]},\n'
           '  ExtendedCoordinateDerivatives -> True, FormatBasis -> {"Partials", "Differentials"}];\n'
           'MyArrayComponents[expr_] := expr // ToBasis[chartM8] // ComponentArray // ToValues // ToValues // Simplify;\n'
           'kδ[lower_, upper_] /; Length[lower] == Length[upper] := Det[Outer[delta, lower, upper]];')
    d.p('**The signature.** `DefMetric[{7, 1, 0}, …]` is the declaration of the reference notebook, taken unchanged: in xAct the list '
        '$\\{7,1,0\\}$ declares seven space-like dimensions ($x_1,\\dots,x_7$), one time-like dimension ($x_0$) and no degenerate one '
        '— the signature $(7,1)$ of $\\eta_{71}=\\mathrm{diag}(-1,+1,\\dots,+1)$ in the sign convention of 4+4.nb (space-like $=+1$). '
        'It is not to be confused with the matrix $\\eta=\\eta_{17}=-\\eta_{71}=\\mathrm{diag}(+1,-1,\\dots,-1)$, which is simply the '
        'squares of the octonion basis: $e_0^2=+1$ for the unit $e_0=1$ (time) and $e_i^2=-1$ for the seven imaginary units (space), '
        'i.e. $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$ and $\\mathrm{Re}(xx)=x_0^2-x_1^2-\\cdots-x_7^2$ for $x=x^Ae_A$. The metrics of this '
        'document are given to xAct with the signs of $\\eta$ ($g_{00}>0$). The declared signature fixes for xAct the sign of the '
        'determinant of the metric, `SignDetOfMetric[g71]` $=-1$, the same in both conventions (a metric with one time-like and seven '
        'space-like directions has a negative determinant either way); the Lovelock tensors follow from the components of the metric, '
        'and they agree exactly with the independent pair-set computation of section 4.5. The notebook checks '
        '`SignatureOfMetric[g71]` $=\\{7,1,0\\}$, `SignDetOfMetric[g71]` $=-1$, $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$ and the quadratic '
        'form $\\mathrm{Re}(xx)=x\\cdot\\eta\\cdot x$ of the octonions. (An earlier version of 7+1.nb declared $\\{1,7,0\\}$, reading '
        'the list as the signs of $\\eta$; it was corrected on 27 October 2026. Both declarations give the same Lovelock tensors.)')
    d.p('While the packages load, their banners and the warnings that xTensor cannot attach rules to '
        '`Commutator` and `Anticommutator` (protected built-in symbols of Wolfram 15, not used here) are suppressed. '
        '`kδ[lower, upper]` is the generalized Kronecker delta $\\delta^{\\text{upper}}_{\\text{lower}}$ with abstract indices; the '
        'Lovelock tensors are then typed exactly as in the reference notebook,')
    d.code('Lovelock1 = -(1/4) RiemannCD[-c,-d,f,i] kδ[{-a,-f,-i},{b,c,d}] // Simplification\n'
           'Lovelock2 = -(1/8) RiemannCD[-c,-d,f,i] RiemannCD[-j,-k,l,m] kδ[{-a,-f,-i,-l,-m},{b,c,d,j,k}] // Simplification\n'
           'Lovelock3 = -(1/16) RiemannCD[-c,-d,f,i] RiemannCD[-j,-k,l,m] RiemannCD[-n,-p,q,r]\n'
           '              kδ[{-a,-f,-i,-l,-m,-q,-r},{b,c,d,j,k,n,p}] // Simplification')
    d.p('i.e. $\\mathrm{Lovelock}_k=E^{(k)b}{}_a$ with the free indices $a$ (down) and $b$ (up) and $R_{cd}{}^{fi}$ = `RiemannCD[-c,-d,f,i]`. '
        'Simplification (xTras) reduces them to curvature monomials; with $R_{ab}{}^{cd}$ the Riemann tensor, $R_a{}^b$ the Ricci tensor and '
        '$R$ the scalar curvature the notebook obtains')
    xl = D.get('xact_lovelock_tex', {}); xi = D.get('xact_lovelock_inputform', {})
    for k in (1, 2, 3):
        t = xl.get(k)
        if t:
            lines = break_sum(r'\mathrm{Lovelock}_{%d}' % k, t, 88, ',' if k < 3 else '.')
            d.align(lines)
        elif xi.get(k):
            d.code('Lovelock%d = %s' % (k, xi[k]))
    d.p('Two checks are made with abstract indices (ToCanonical): $\\mathrm{Lovelock}_1-(R_a{}^b-\\tfrac12\\delta_a{}^bR)=0$, and the trace '
        '$\\mathrm{Lovelock}_2{}_a{}^a=-2L_2$ with $L_2=R^2-4R_{cd}R^{cd}+R_{cdfi}R^{cdfi}$. The reference notebook sets the option '
        '`UseMetricOnVBundle -> None` of ToCanonical (indices are not moved up and down); for the trace identity the metric must identify the '
        'dummy pairs $R_{cd}R^{cd}$ and $R^c{}_dR_c{}^d$, so that one call uses `UseMetricOnVBundle -> All`.')
    d.h2('4.4 Components with xAct: CD = LC[g]')
    d.p('For a metric given as an 8×8 matrix of components with lower indices the reference notebook makes it a CTensor in the basis of '
        '`chartM8`, lets MetricCompute compute and simplify its curvature, and sets `CD = LC[g]` ("xAct magic": the abstract covariant '
        'derivative becomes the Levi-Civita connection of the component metric). After `RiemannCD = Riemann[CD]`, `RicciCD = Ricci[CD]`, '
        '`RicciScalarCD = RicciScalar[CD]` and `EinsteinCD = Einstein[CD]` every abstract expression evaluates to components. The notebook '
        'function `xActLovelock[gm]` does exactly these steps:')
    d.code('xActLovelock[gm_] := Module[{res},\n'
           '   g71 = CTensor[gm /. toXc, {-chartM8, -chartM8}];\n'
           '   MetricCompute[g71, chartM8, All, Parallelize -> False, Verbose -> False];\n'
           '   CD = LC[g71];\n'
           '   RiemannCD = Riemann[CD]; RicciCD = Ricci[CD]; RicciScalarCD = RicciScalar[CD]; EinsteinCD = Einstein[CD];\n'
           '   res = Transpose[asMat8[MyArrayComponents[#]]] & /@ {Lovelock1, Lovelock2, Lovelock3, EinsteinCD[-a, b]};\n'
           '   res /. fromXc]')
    d.p('Here `toXc` replaces $x_\\mu$ by the coordinate scalar `xμ[]` and `fromXc` undoes it, `asMat8` turns a vanishing result into the '
        '8×8 zero matrix, and the Transpose makes row $\\mu$, column $\\nu$ hold $E^{(k)\\mu}{}_\\nu$ (the array of MyArrayComponents has '
        'the lower index $a$ first; the pp-wave of section 4.7, whose $E^{(1)\\mu}{}_\\nu$ is not a symmetric matrix, fixes this order). '
        'For the cosmological metric `xActLovelock` gives $\\mathrm{Lovelock}_1=$ `EinsteinCD` $=$ the Einstein tensor of section 3, and the '
        'closed forms of section 4.6.')
    d.h2('4.5 An independent computation: the pair-set algorithm')
    d.p('The same tensors are also computed without xAct. A direct evaluation of the generalized delta would run over $8^{4k+2}$ index '
        'combinations; the notebook functions `pairSets`, `orderedSeqs`, `lovelockE`, `lovelockL` (and tools/lovelock71.py in Python) use '
        'the antisymmetries instead. Let $\\mathcal U$ run over the SETS of $k$ disjoint index pairs $(\\alpha<\\beta)$ not containing $\\mu$, '
        'and $\\mathcal V$ over the ORDERED sequences of $k$ disjoint pairs $(\\gamma<\\delta)$ that exhaust '
        '$(\\mathcal U\\cup\\lbrace\\mu\\rbrace)\\setminus\\lbrace\\nu\\rbrace$. Each pair contributes a factor 2 (both orders of a pair give the same term), '
        'the $k!$ orderings of the pairs of $\\mathcal U$ give the same sum, and')
    d.eq(r'E^{(k)\mu}{}_{\nu}=-2^{k-1}k!\sum_{\mathcal U}\sum_{\mathcal V}\mathrm{sgn}(\mu\,\mathcal U\to\nu\,\mathcal V)\prod_{i=1}^{k}R^{\mathcal V_i}{}_{\mathcal U_i},\qquad '
         r'L_k=2^kk!\sum_{\mathcal U}\sum_{\mathcal V}\mathrm{sgn}(\mathcal U\to\mathcal V)\prod_{i=1}^{k}R^{\mathcal V_i}{}_{\mathcal U_i},')
    d.p('where sgn is the sign of the permutation that turns the upper index sequence into the lower one (in Mathematica '
        '`Signature[up] Signature[dn]`). For $k=3$ and fixed $\\mu,\\nu$ there are 105 upper pair-sets and 90 ordered lower sequences. '
        'The notebook compares $E^{(1)}$ with the brute-force contraction $-\\tfrac14\\delta^{\\mu\\alpha\\beta}_{\\nu\\gamma\\delta}R^{\\gamma\\delta}{}_{\\alpha\\beta}$, '
        '$E^{(2)}$ with the Lanczos tensor, and $E^{(1)},E^{(2)},E^{(3)}$ of the cosmological metric and of the pp-wave with xAct: the two '
        'computations agree exactly. The pair-set sum also works on a table of exact rational numbers (section 4.7).')
    d.h2('4.6 Closed forms for the cosmological metric')
    d.p('For the cosmological metric every $E^{(k)}$ is diagonal; the entry $E^{(k)\\mu}{}_\\mu$ (no sum) is $-\\tfrac12$ times the '
        'density $L_k$ restricted to the index pairs that avoid $\\mu$. The results (Ha = $H_a$, dHa = $H_a\'$, and so on) are:')
    cf = D.get('closed_forms_tex', {})
    names = {0: '0}{}_0', 1: '1}{}_1', 4: '4}{}_4'}
    for k in (1, 2, 3):
        lines = []
        for c in (0, 1, 4):
            lines += break_sum('E^{(%d)%s' % (k, names[c]), cf.get((k, c), '?'), 95, ',' if c != 4 else '.')
        d.align(lines)
    d.p('In particular')
    d.eq(r'E^{(2)0}{}_0=-12H_b\big(4H_a^3+18H_a^2H_b+12H_aH_b^2+H_b^3\big),\qquad E^{(3)0}{}_0=360\,H_a^2H_b^3\big(4H_a+3H_b\big).')
    d.p('Divergence-freeness becomes, for each $k$,')
    d.eq(r"\frac{d}{dx_0}E^{(k)0}{}_0+3H_a\big(E^{(k)0}{}_0-E^{(k)1}{}_1\big)+4H_b\big(E^{(k)0}{}_0-E^{(k)4}{}_4\big)=0,")
    d.p('checked for arbitrary $a,b$. The VARIATIONAL ORIGIN is checked as well: with a lapse function $N(x_0)$ ($g_{00}=N^2$) the reduced '
        'Lagrangian is $N a^3b^4L_k$, and its Euler–Lagrange expressions at $N=1$ are')
    d.eq(r'\frac{\delta(Na^3b^4L_k)}{\delta N}=-2a^3b^4E^{(k)0}{}_0,\qquad \frac{\delta(Na^3b^4L_k)}{\delta a}=-6a^2b^4E^{(k)1}{}_1,\qquad '
         r'\frac{\delta(Na^3b^4L_k)}{\delta b}=-8a^3b^3E^{(k)4}{}_4,')
    d.p('for $k=1,2,3,4$ (for $k=4$ all three vanish identically: $\\sqrt{|g|}L_4$ is a total derivative). The factors come from '
        '$\\delta g^{00}=-2\\delta N$, three $\\delta g^{ii}=2\\delta a/a^3$ and four $\\delta g^{kk}=2\\delta b/b^3$.')
    d.h2('4.7 An inhomogeneous metric and a gravitational wave')
    d.p('For the explicit inhomogeneous metric $g=\\mathrm{diag}(n^2,-a^2,-a^2,-a^2,-b^2,-b^2,-b^2,-b^2)$ with $n=1+x_0x_4/5+x_0^2/11$, '
        '$a=1+x_0/3+x_4^2/7$, $b=2-x_0x_4/4+x_0^2/9+x_4/13$, '
        'the divergence $\\nabla_\\mu E^{(k)\\mu}{}_\\nu$ is evaluated EXACTLY (rational arithmetic) at $x_0=1/2$, $x_4=1/3$ for $k=1,2,3$; '
        'it vanishes. The derivative of $E^{(k)}$ (a polynomial of degree $k$ in the curvature) is obtained from the curvature and its '
        'first derivatives at the point: $\\partial_\\lambda E^{(k)}=\\frac{d}{d\\epsilon}E^{(k)}[R+\\epsilon\\,\\partial_\\lambda R]\\big|_{\\epsilon=0}$. '
        'At that point $E^{(2)}$ equals the Lanczos tensor exactly, and')
    e304 = nm.get('E^(3)0_4 at the point', '?')
    d.eq(r'E^{(3)0}{}_4\big|_{x_0=1/2,\,x_4=1/3}=%s .' % _frac_tex(e304))
    d.p('For the pp-wave $ds^2=dx_0^2-dx_1^2-\\cdots-dx_7^2+F(x_0-x_1,x_2,x_3)\\,(dx_0-dx_1)^2$ with an arbitrary profile $F$ and the null '
        'vector $l_\\mu=(1,-1,0,\\dots,0)$,')
    d.eq(r'E^{(1)}_{\mu\nu}=\tfrac12\big(\partial_2^2+\partial_3^2\big)F\;l_\mu l_\nu,\qquad E^{(2)}=E^{(3)}=0\ \text{for every profile }F,')
    d.p('so a plane wave whose profile is harmonic in the transverse directions solves the Einstein–Lovelock equations for every '
        '$\\alpha_2,\\alpha_3$ (with $\\bar\\Lambda=0$). xAct and the pair-set sum agree for this metric, which is not diagonal.')
    d.h2('4.8 Exponential vacuum solutions: eternal inflation of ordinary space and deflation of the auxiliary space')
    d.p('The procedure of the reference notebook — solve the vacuum equations of section 4.2 for $w_2$, $w_3$ (and $\\Lambda$) — is applied '
        'to the cosmological metric with constant Hubble rates, $a=e^{H_a x_0}$, $b=e^{H_b x_0}$, $H_a=H$, $H_b=q_HH$ ($q_H$ a pure number; '
        'code `qH`). With $H_a\'=H_b\'=0$ in the closed forms of section 4.6 every $E^{(k)}$ is a constant diagonal matrix proportional to '
        '$H^{2k}$, and the 64 equations reduce to three distinct ones (components 00, 11, 44). They are not independent: for constant Hubble '
        'rates the divergence identity of section 4.6 becomes')
    d.eq(r'3H_a\big(\mathrm{eq}_{00}-\mathrm{eq}_{11}\big)+4H_b\big(\mathrm{eq}_{00}-\mathrm{eq}_{44}\big)=0,')
    d.p('so for every $(H_a,H_b)$ there is a one-parameter family of couplings: given $w_1$ and $\\Lambda$ the equations fix $w_2$, $w_3$. '
        'For $q_H=-1$ — ordinary space expands as $e^{Hx_0}$ while the auxiliary space contracts as $e^{-Hx_0}$, for every time $x_0$ '
        '(eternal inflation of ordinary space with eternal deflation of the auxiliary space) — the three equations are')
    ex = D.get('expo') or {}
    te = ex.get('tex_eq_qm1', {})
    d.eq(r'\mathrm{eq}_{00}=%s,\qquad \mathrm{eq}_{11}=%s,\qquad \mathrm{eq}_{44}=%s,' % (te.get(0, '?'), te.get(1, '?'), te.get(4, '?')))
    ts = ex.get('tex_sol_qm1', {}); al = ex.get('alpha_qm1', ('?', '?'))
    d.p('and the family is')
    d.eq(r'w_2=%s,\qquad w_3=%s;\\ \Lambda=0:\quad \frac{w_2}{w_1}=%s,\ \ \frac{w_3}{w_1}=%s,\quad\text{i.e.}\quad '
         r'\alpha_2=\frac{w_2}{w_1H^2}=%s\,H^{-2},\ \ \alpha_3=\frac{w_3}{w_1H^4}=%s\,H^{-4}.'
         % (ts.get('w_2', '?'), ts.get('w_3', '?'), _tex_num(al[0]), _tex_num(al[1]), _tex_num(al[0]), _tex_num(al[1])))
    d.p('For general $q_H$ (computed here from the closed forms of section 4.6; the notebook and the Python program obtain the same '
        'expressions, and check that they solve all 64 components for every $\\Lambda$):')
    d.eq(r'w_2=%s,' % _ratio_tex(ex, 'w_2'))
    d.eq(r'w_3=%s.' % _ratio_tex(ex, 'w_3'))

    # ==============================================================================================
    d.h1('5. Generalized frame matrices, canonical spin connection, total covariant derivative (section 13)')
    d.h2('5.1 Frame field and generalized frame matrices')
    d.p('A frame field (vielbein) is a square root of the metric, and its inverse is written $e_A{}^\\mu$:')
    d.eq(r'g_{\mu\nu}=\eta_{AB}\,e^A{}_\mu e^B{}_\nu,\qquad e_A{}^\mu e^A{}_\nu=\delta^\mu_\nu .')
    d.p('The GENERALIZED FRAME MATRICES are the position-dependent real 16×16 matrices')
    d.eq(r'\Gamma_\mu(X)=e^A{}_\mu(X)\,\Gamma_A,\qquad \Gamma^\mu(X)=e_A{}^\mu(X)\,\Gamma^A,\qquad '
         r'\Gamma_\mu\Gamma_\nu+\Gamma_\nu\Gamma_\mu=2g_{\mu\nu}(X)\,1_{16},')
    d.p('with $\\Gamma^A=\\eta^{AA}\\Gamma_A$ (no sum). They are real because the frame field and the $\\Gamma_A$ are real.')
    d.h2('5.2 The canonical spin connection and the total covariant derivative')
    d.p('The canonical (Levi-Civita) spin connection and its action on 16-component spinors are')
    d.align([r'\omega_\mu{}^A{}_B&=e^A{}_\nu\big(\partial_\mu e_B{}^\nu+\{{}^{\nu}_{\mu\lambda}\}e_B{}^\lambda\big),'
             r'\qquad \omega_{\mu AB}=\eta_{AC}\,\omega_\mu{}^C{}_B=-\omega_{\mu BA},',
             r'\Omega_\mu&=\tfrac14\,\omega_{\mu AB}\,\Gamma^A\Gamma^B,\qquad D_\mu\psi=\partial_\mu\psi+\Omega_\mu\psi,\qquad '
             r'D_\mu\bar\psi=\partial_\mu\bar\psi-\bar\psi\,\Omega_\mu .'])
    d.p('The TOTAL covariant derivative acts on every index of an object: with the Christoffel symbols on coordinate indices, with '
        '$\\omega$ on frame indices, and through the commutator with $\\Omega$ on the two spinor indices of a 16×16 matrix. The '
        'canonical spin connection is the one for which the total covariant derivative of the frame field and of every frame '
        'matrix vanishes:')
    d.align([r'D_\mu e^A{}_\nu&=\partial_\mu e^A{}_\nu-\{{}^{\lambda}_{\mu\nu}\}e^A{}_\lambda+\omega_\mu{}^A{}_B\,e^B{}_\nu=0\qquad\text{(vielbein postulate)},',
             r'\nabla_\mu\Gamma_\nu&=\partial_\mu\Gamma_\nu-\{{}^{\lambda}_{\mu\nu}\}\Gamma_\lambda+[\Omega_\mu,\Gamma_\nu]=0,',
             r'D_\mu\Gamma^A&=\omega_\mu{}^A{}_B\,\Gamma^B+[\Omega_\mu,\Gamma^A]=0 .'])
    d.p('$\\Omega_\\mu$ is real and $\\Gamma_0\\Omega_\\mu^{\\mathsf T}\\Gamma_0=-\\Omega_\\mu$, which makes $D_\\mu\\bar\\psi$ the Dirac adjoint '
        'of $D_\\mu\\psi$ and the action below real.')
    d.h2('5.3 Spin curvature, Bianchi identity, Lichnerowicz')
    d.p('The curvature of the spin connection is the Riemann tensor in spinor form:')
    d.align([r'\mathcal F_{\mu\nu}&=\partial_\mu\Omega_\nu-\partial_\nu\Omega_\mu+[\Omega_\mu,\Omega_\nu]=[D_\mu,D_\nu]'
             r'=\tfrac14\,R_{AB\mu\nu}\,\Gamma^A\Gamma^B,\qquad R_{AB\mu\nu}=\eta_{AC}\,e^C{}_\rho\,R^\rho{}_{\sigma\mu\nu}\,e_B{}^\sigma,',
             r'0&=\partial_\lambda \mathcal F_{\mu\nu}+[\Omega_\lambda,\mathcal F_{\mu\nu}]+\partial_\mu \mathcal F_{\nu\lambda}+[\Omega_\mu,\mathcal F_{\nu\lambda}]'
             r'+\partial_\nu \mathcal F_{\lambda\mu}+[\Omega_\nu,\mathcal F_{\lambda\mu}]\qquad\text{(Bianchi)},',
             r'\tfrac12\,\Gamma^\mu\Gamma^\nu \mathcal F_{\mu\nu}&=-\tfrac{R}{4}\,1_{16},\qquad (\Gamma^\mu D_\mu)^2\psi=g^{\mu\nu}\big(\partial_\mu D_\nu\psi'
             r'+\Omega_\mu D_\nu\psi-\{{}^{\lambda}_{\mu\nu}\}D_\lambda\psi\big)-\tfrac{R}{4}\psi .'])
    d.p('Every identity of sections 5.1–5.3 is checked by the notebook (function `frameChecks`) and by the Python program for '
        'four metrics: the cosmological metric with the diagonal frame $e=\\mathrm{diag}(1,a,a,a,b,b,b,b)$; the pp-wave with the '
        'non-diagonal frame $e^0=(1+F/2)dx_0-(F/2)dx_1$, $e^1=(F/2)dx_0+(1-F/2)dx_1$, $e^A=dx^A$ otherwise; the inhomogeneous '
        'metric with $e=\\mathrm{diag}(n,a,a,a,b,b,b,b)$ (exactly at $x_0=1/2$, $x_4=1/3$, the derivatives being taken symbolically first); '
        'and the static radial metric of section 5.4.')
    d.h2('5.4 Cartan’s first structure equation; a static metric with a radial coordinate')
    d.p('With the frame one-forms $e^A=e^A{}_\\mu dx^\\mu$ and the connection one-forms $\\omega^A{}_B=\\omega_\\mu{}^A{}_B\\,dx^\\mu$, the '
        'vielbein postulate antisymmetrized in $\\mu,\\nu$ (the Christoffel terms cancel) is Cartan’s first structure equation without torsion:')
    d.eq(r'de^A+\omega^A{}_B\wedge e^B=0\quad\Longleftrightarrow\quad \partial_\mu e^A{}_\nu-\partial_\nu e^A{}_\mu+\omega_\mu{}^A{}_B\,e^B{}_\nu-\omega_\nu{}^A{}_B\,e^B{}_\mu=0 .')
    d.p('It determines the canonical spin connection from the frame alone. With the structure coefficients $C^A{}_{BC}=-C^A{}_{CB}$ and the '
        'connection written with a frame form index,')
    d.align([r'de^A&=\tfrac12\,C^A{}_{BC}\,e^B\wedge e^C,\qquad C^A{}_{BC}=e_B{}^\mu e_C{}^\nu\big(\partial_\mu e^A{}_\nu-\partial_\nu e^A{}_\mu\big),\qquad C_{ABC}=\eta_{AD}C^D{}_{BC},',
             r'\omega_{C,AB}&\equiv e_C{}^\mu\,\omega_{\mu AB}=-\tfrac12\big(C_{ACB}+C_{BAC}-C_{CBA}\big),'])
    d.p('the unique solution with $\\omega_{C,AB}=-\\omega_{C,BA}$; both relations are checked for all four frames. As an example take '
        '$r=x_1>0$ and arbitrary positive functions $f(r)$, $h(r)$ (code `fR[x1]`, `hR[x1]`):')
    d.eq(r'ds^2=f(r)\,dx_0^2-h(r)\,dr^2-r^2\big(dx_2^2+dx_3^2+dx_4^2+dx_5^2+dx_6^2+dx_7^2\big),\\ e^0=\sqrt f\,dx_0,\ \ e^1=\sqrt h\,dr,\ \ e^k=r\,dx^k\ (k=2,\dots,7).')
    d.p('The six directions $x_2,\\dots,x_7$ are flat directions scaled by $r$ (a static "planar" metric of 7+1 spacetime, not a spherically '
        'symmetric one). Cartan’s equation gives $de^0=\\frac{f\'}{2\\sqrt f}\\,dr\\wedge dx_0=-\\omega^0{}_1\\wedge e^1$ and '
        '$de^k=dr\\wedge dx^k=-\\omega^k{}_1\\wedge e^1$, hence $\\omega^0{}_1=\\frac{f\'}{2\\sqrt{fh}}\\,dx_0$, $\\omega^k{}_1=\\frac{1}{\\sqrt h}\\,dx^k$, and')
    d.align([r"\Omega_0&=\frac{f'}{4\sqrt f\sqrt h}\,\Gamma_1\Gamma_0,\qquad \Omega_1=0,\qquad \Omega_k=\frac{1}{2\sqrt h}\,\Gamma_1\Gamma_k\quad(k=2,\dots,7),",
             r"\Gamma^\mu\Omega_\mu&=\frac{1}{\sqrt h}\Big(\frac{f'}{4f}+\frac3r\Big)\Gamma^1,\qquad \Gamma^1=\eta^{11}\Gamma_1=-\Gamma_1,"])
    d.p('the $3/r=6\\times\\frac{1}{2r}$ coming from the six scaled directions. The covariant Dirac operator and a rescaling that removes the '
        'connection are therefore')
    d.align([r"i\Gamma^\mu D_\mu-m&=\frac{i}{\sqrt f}\,\Gamma^0\partial_0+\frac{i}{\sqrt h}\,\Gamma^1\Big(\partial_r+\frac{f'}{4f}+\frac3r\Big)+\sum_{k=2}^{7}\frac{i}{r}\,\Gamma^k\partial_k-m,",
             r"\psi&=f^{-1/4}r^{-3}\chi:\qquad \Gamma^\mu D_\mu\psi=f^{-1/4}r^{-3}\,\Gamma^\mu\partial_\mu\chi ."])

    # ==============================================================================================
    d.h1('6. The covariant Dirac equation of dirac16complex')
    d.p('The Lagrangian density and the field equation are')
    d.eq(r'\mathcal L=\sqrt{|g|}\;\bar\psi\big(i\,\Gamma^\mu D_\mu-m\big)\psi,\qquad \big(i\,\Gamma^\mu(X)\,D_\mu-m\big)\psi=0,')
    d.p('where the spin connection $\\Omega_\\mu$ in $D_\\mu$ is the coupling of gravity to dirac16complex. The current '
        '$J^\\mu=\\bar\\psi\\Gamma^\\mu\\psi$ is conserved because, for arbitrary $\\psi$ and $\\bar\\psi$ (by $\\nabla\\Gamma=0$ and '
        '$\\partial_\\mu\\sqrt{|g|}=\\sqrt{|g|}\\{{}^{\\lambda}_{\\lambda\\mu}\\}$),')
    d.eq(r'\partial_\mu\big(\sqrt{|g|}\,\bar\psi\Gamma^\mu\psi\big)=\sqrt{|g|}\,\big[(D_\mu\bar\psi)\Gamma^\mu\psi+\bar\psi\Gamma^\mu D_\mu\psi\big],')
    d.p('and the bracket vanishes when $\\psi$ and $\\bar\\psi$ solve the field equation and its adjoint. Squaring with the '
        'Lichnerowicz formula gives $\\big(g^{\\mu\\nu}\\nabla_\\mu D_\\nu+m^2-\\tfrac{R}{4}\\big)\\psi=0$.')
    d.p('**Coupling to a gauge field.** An abelian gauge field $A_\\mu(X)$ with charge $q$ enters through the gauge-covariant derivative')
    d.eq(r'D_\mu\psi=\partial_\mu\psi+\Omega_\mu\psi-iqA_\mu\psi,\qquad D_\mu\bar\psi=\partial_\mu\bar\psi-\bar\psi\,\Omega_\mu+iqA_\mu\bar\psi .')
    d.p('Under $\\psi\\to e^{iq\\alpha}\\psi$, $A_\\mu\\to A_\\mu+\\partial_\\mu\\alpha$ ($\\alpha(X)$ arbitrary) the Dirac operator is covariant, '
        '$\\Gamma^\\mu D\'_\\mu(e^{iq\\alpha}\\psi)=e^{iq\\alpha}\\,\\Gamma^\\mu D_\\mu\\psi$, and the current identity above holds unchanged, so the '
        'electric current $q\\,\\bar\\psi\\Gamma^\\mu\\psi$ is conserved. Both statements are checked with the cosmological frame and arbitrary '
        '$A_\\mu(x_0,x_1,x_5)$, $\\alpha(x_0,x_1,x_5)$.')
    d.h2('6.1 The cosmological spacetime')
    d.p('For the cosmological metric the spin connection is NOT zero whenever space expands:')
    d.eq(r"\Omega_0=0,\qquad \Omega_i=\tfrac{a'}{2}\,\Gamma_i\Gamma_0\ (i=1,2,3),\qquad \Omega_k=\tfrac{b'}{2}\,\Gamma_k\Gamma_0\ (k=4,\dots,7),"
         r"\qquad \Gamma^\mu\Omega_\mu=\Big(\tfrac32H_a+2H_b\Big)\Gamma_0 .")
    d.p('The rescaled field $\\chi=(a^3b^4)^{1/2}\\psi$ obeys an equation without connection, '
        '$\\Gamma^\\mu D_\\mu\\psi=(a^3b^4)^{-1/2}\\Gamma^\\mu\\partial_\\mu\\chi$. For a plane wave '
        '$\\chi=e^{i(\\vec p\\cdot\\vec x+\\vec q\\cdot\\vec y)}c(x_0)$ — $\\vec p=(p_1,p_2,p_3)$ the momentum along ordinary space $\\vec x=(x_1,x_2,x_3)$, '
        '$\\vec q=(q_4,\\dots,q_7)$ along the auxiliary space $\\vec y=(x_4,\\dots,x_7)$ — the Dirac equation becomes')
    d.eq(r'i\,\frac{dc}{dx_0}=h(x_0)\,c,\qquad h(x_0)=\sum_{i=1}^{3}\alpha_i\,\frac{p_i}{a}+\sum_{k=4}^{7}\alpha_k\,\frac{q_k}{b}+\beta\,m,'
         r'\qquad \beta=\Gamma_0,\ \ \alpha_j=\Gamma^0\Gamma^j=\begin{pmatrix}0&\tau^O_j\\-\tau^O_j&0\end{pmatrix},')
    d.p('the flat-space Hamiltonian with the physical (redshifted) momenta $\\vec p/a$ and $\\vec q/b$.')
    d.h2('6.2 Conformal weight 7/2')
    d.p('For a conformally flat metric $g=C(x_0)^2\\eta$ ($x_0$ is then conformal time) the massless operator satisfies, for every $f$,')
    d.eq(r'\Gamma^\mu D_\mu\big(C^{-7/2}f\big)=C^{-9/2}\,\Gamma^A\partial_Af,')
    d.p('so a massless dirac16complex in a conformally flat 7+1 spacetime is a rescaled flat-space solution and no pairs are created. '
        'The cosmological metric is conformally flat only when $a=b$.')
    d.h2('6.3 Two classes of states in an anisotropic expansion')
    d.p('With unit vectors $\\vec n_a$, $\\vec n_b$ along $\\vec p$ and $\\vec q$ the Hamiltonian is '
        '$h=\\frac{|\\vec p|}{a}\\mathcal A+\\frac{|\\vec q|}{b}\\mathcal B+m\\beta$ with the CONSTANT real matrices $\\mathcal A=\\sum_i n_{a,i}\\alpha_i$, $\\mathcal B=\\sum_k n_{b,k}\\alpha_k$. '
        '$\\mathcal A$, $\\mathcal B$, $\\beta$ square to $1_{16}$ and anticommute; $\\mathcal Z=\\mathcal A\\mathcal B\\beta$ squares to $-1_{16}$, is antisymmetric, and commutes with '
        '$\\mathcal A$, $\\mathcal B$, $\\beta$ and $h$, so its eigenvalue $\\pm i$ is conserved. On $\\mathcal Z=+i$ the three matrices act like the Pauli matrices '
        '$(\\sigma_1,\\sigma_2,\\sigma_3)$, on $\\mathcal Z=-i$ like $(\\sigma_1,\\sigma_2,-\\sigma_3)$; the 16-component mode equation is four copies of each of')
    d.eq(r'i\,\frac{dc}{dx_0}=\Big(\frac{|\vec p|}{a}\sigma_1+\frac{|\vec q|}{b}\sigma_2\pm m\,\sigma_3\Big)c,\qquad c\in\mathbb C^2 .')
    d.p('Pairs are created when the direction of the physical momentum $(|\\vec p|/a,|\\vec q|/b)$ turns fast compared with the frequency '
        '$\\omega=\\sqrt{|\\vec p|^2/a^2+|\\vec q|^2/b^2+m^2}$. The Bogoliubov coefficient $|\\beta|^2$ of a mode is the probability that a '
        'positive-energy state at the initial time ends in a negative-energy state at the final time; $|\\alpha|^2+|\\beta|^2=1$.')

    # ==============================================================================================
    d.h1('7. The three epochs (section 14)')
    d.p('For the cosmological metric with $T^\\mu{}_\\nu=\\mathrm{diag}(\\varepsilon,-p_a,-p_a,-p_a,-p_b,-p_b,-p_b,-p_b)$ (energy density '
        '$\\varepsilon$, pressures $p_a$ along ordinary space and $p_b$ along the auxiliary space) the field equations are')
    d.eq(r'\sum_k\alpha_kE^{(k)0}{}_0=\kappa\varepsilon,\qquad \sum_k\alpha_kE^{(k)1}{}_1=-\kappa p_a,\qquad \sum_k\alpha_kE^{(k)4}{}_4=-\kappa p_b,')
    d.p('and they imply the conservation law $\\varepsilon\'+3H_a(\\varepsilon+p_a)+4H_b(\\varepsilon+p_b)=0$.')
    d.h2('7.1 Primordial epoch (near $x_0=0$): Kasner solutions and dynamical compactification')
    d.p('For $a=x_0^{p}$, $b=x_0^{q}$ every term of $E^{(k)}$ scales as $x_0^{-2k}$: near $x_0=0$ the highest Lovelock order with a '
        'non-zero coupling dominates, and matter whose density grows more slowly than $x_0^{-2k}$ is negligible. With $H_a=p/x_0$, '
        '$H_b=q/x_0$, $H_a\'=-p/x_0^2$, $H_b\'=-q/x_0^2$ in the closed forms of section 4.6 the vacuum solutions of each order are:')
    gb = nm.get('Gauss-Bonnet Kasner p', '')
    gbl = mlist(gb) or [None, None, None]
    d.ul(['**Einstein** ($k=1$): $3p+4q=1$ and $3p^2+4q^2=1$, i.e. $p=(1\\pm2\\sqrt2)/7$, $q=(2\\mp3\\sqrt2)/14$. On the branch '
          '$p=0.5469$, $q=-0.1602$ ordinary space expands while the auxiliary space contracts as $x_0$ grows: a dynamical compactification of '
          '$x_4,\\dots,x_7$.',
          '**Gauss–Bonnet** ($k=2$): $3p+4q=3$, and $p$ is a root of $-203p^3+81p^2+351p+27=0$: $p=%s$, $%s$, $%s$ (with '
          '$q=(3-3p)/4$).' % tuple(fmt(x, 8) for x in gbl),
          '**Cubic Lovelock** ($k=3$): the non-degenerate solution $(p,q)=(-15/7,\\,20/7)$ with $3p+4q=5$; $E^{(3)}$ vanishes '
          'identically on the degenerate families $q=0$ (static auxiliary space) and $p=0$.'])
    d.p('The pure-order equations are (each multiplied by $x_0^{2k}$; columns 00, 11, 44):')
    ek = D.get('kasner_tex', {})
    for k in (1, 2, 3):
        lines = []
        for c in (0, 1, 4):
            lines += break_sum('x_0^{%d}E^{(%d)%s' % (2*k, k, {0: '0}{}_0', 1: '1}{}_1', 4: '4}{}_4'}[c]), ek.get((k, c), '?'), 95, ',' if c != 4 else '.')
        d.align(lines)
    d.h2('7.2 Pair creation in the primordial epoch')
    d.p('On the Einstein–Kasner branch a massless mode depends on $(|\\vec p|,|\\vec q|)$ only through the scaling variable '
        '$K=|\\vec p|\\,\\lambda^{1-p}$, $\\lambda=(|\\vec q|/|\\vec p|)^{1/(q-p)}$ ($x_0\\to\\lambda x_0$ maps one problem onto the other). '
        'The evolution is adiabatic before and after the time at which $|\\vec p|/a\\approx|\\vec q|/b$, so it is integrated from '
        '$10^{-15}\\lambda$ to $300\\lambda$:')
    kb = [nm.get('Kasner beta2 (1,1)'), nm.get('Kasner beta2 (2,1)'), nm.get('Kasner beta2 (1,3)')]
    kK = [nm.get('Kasner K (1,1)'), nm.get('Kasner K (2,1)'), nm.get('Kasner K (1,3)')]
    rk = ref.get('Kasner (Einstein branch), massless: |beta|^2 for (|p|, |q|) = (1,1), (2,1), (1,3)', '')
    rkv = _pylist(rk)
    d.table(['$(|\\vec p|,|\\vec q|)$', '$K$', '$|\\beta|^2$ (Mathematica)', '$|\\beta|^2$ (Python)'],
            [['$(1,1)$', fmt(mnum(kK[0] or '') if kK[0] else None, 6), fmt(mnum(kb[0]) if kb[0] else None, 8), fmt(rkv[0] if rkv else None, 8)],
             ['$(2,1)$', fmt(mnum(kK[1] or '') if kK[1] else None, 6), fmt(mnum(kb[1]) if kb[1] else None, 8), fmt(rkv[1] if rkv else None, 8)],
             ['$(1,3)$', fmt(mnum(kK[2] or '') if kK[2] else None, 6), fmt(mnum(kb[2]) if kb[2] else None, 8), fmt(rkv[2] if rkv else None, 8)]],
            widths=[0.2, 0.2, 0.3, 0.3])
    d.p('The momenta $(1.4302\\ldots,2.5)$ have $K=1$ and give the same $|\\beta|^2$ as $(1,1)$; an isotropic expansion creates no massless '
        'pairs ($|\\beta|^2<10^{-20}$). With a mass the two classes $\\mathcal Z=\\pm i$ are created at different rates: for $m=0.3$, '
        '$|\\vec p|=1$, $|\\vec q|=1.5$, $x_0$ from 0.05 to 40,')
    b16 = nm.get('beta2 16x16'); bp = nm.get('beta2 2x2 +m'); bm = nm.get('beta2 2x2 -m')
    d.eq(r'|\beta|^2_{16\times16}=%s=\tfrac12\big(|\beta|^2_{+m}+|\beta|^2_{-m}\big),\qquad |\beta|^2_{+m}=%s,\quad |\beta|^2_{-m}=%s .'
         % (fmt(mnum(b16) if b16 else None, 8), fmt(mnum(bp) if bp else None, 8), fmt(mnum(bm) if bm else None, 8)))
    d.h2('7.3 Modern epoch: a static auxiliary space')
    d.p('With $b=b_0$ ($H_b=0$) the Lovelock tensors reduce to (entries 00, 11, 44)')
    d.eq(r"E^{(1)}=\mathrm{diag}\big(3H_a^2,\ 2H_a'+3H_a^2,\ 3H_a'+6H_a^2\big),\qquad E^{(2)}=\mathrm{diag}\big(0,\,0,\,-12H_a^2(H_a'+H_a^2)\big),\qquad E^{(3)}=0 .")
    d.p('The 00 and 11 equations are the Friedmann equations of ordinary cosmology,')
    d.eq(r"3H_a^2=\kappa\varepsilon+\Lambda=8\pi G_4\,\rho_4+\Lambda,\qquad 2H_a'+3H_a^2=-\kappa p_a+\Lambda,\qquad G_4=\frac{G_8}{V_\perp},\quad V_\perp=b_0^4V_c,")
    d.p('for matter confined to ordinary space ($\\varepsilon=\\rho_4/V_\\perp$; $V_c$ the coordinate volume of the auxiliary space). '
        'The 44 equation then FIXES the stress that holds $b$ constant: $\\kappa p_b=\\Lambda-3H_a\'-6H_a^2+12\\alpha_2H_a^2(H_a\'+H_a^2)$ — the '
        'analogue of the fold fluid of Dirac_claude. A mode with auxiliary momentum $\\vec q$ moves in ordinary space as a particle of '
        'mass $\\sqrt{m^2+|\\vec q|^2/b_0^2}$ (a Kaluza–Klein tower on a torus). Pair creation today is suppressed by $e^{-2\\pi M/H_0}$ '
        '(section 7.4) with $H_0\\approx1.4\\times10^{-42}$ GeV, i.e. absent.')
    d.h2('7.4 Far future: de Sitter expansion and thermal pair creation')
    d.p('Eight-dimensional de Sitter space $a=b=e^{Hx_0}$ is an exact vacuum solution when all $E^{(k)}$ are proportional to $\\delta$:')
    d.eq(r'E^{(1)}=21H^2\,\delta,\quad E^{(2)}=-420H^4\,\delta,\quad E^{(3)}=2520H^6\,\delta\qquad\Longrightarrow\qquad 21\alpha_1H^2-420\alpha_2H^4+2520\alpha_3H^6=\Lambda .')
    d.p('Over a static auxiliary space ($a=e^{Hx_0}$, $b=b_0$): $E^{(1)}=\\mathrm{diag}(3,3,6)H^2$, $E^{(2)}=\\mathrm{diag}(0,0,-12)H^4$, '
        '$E^{(3)}=0$. In both cases a mode of dirac16complex obeys $i\\,dc/dx_0=(k\\,e^{-Hx_0}\\sigma_1+M\\sigma_3)c$, with $M=m$, or with the '
        'Kaluza–Klein mass $M=\\sqrt{m^2+|\\vec q|^2/b_0^2}$. Starting from the adiabatic vacuum at early times the number of created pairs per '
        'mode is exactly the Fermi–Dirac occupation at the Gibbons–Hawking temperature $T=H/(2\\pi)$, independent of $k$:')
    d.eq(r'|\beta|^2=\frac{1}{e^{2\pi M/H}+1}.')
    dsv = [nm.get('dS beta2 M/H=0.25'), nm.get('dS beta2 M/H=0.5'), nm.get('dS beta2 M/H=1')]
    import math
    d.table(['$M/H$', '$|\\beta|^2$ (Mathematica)', '$1/(e^{2\\pi M/H}+1)$'],
            [['%s' % mh, fmt(mnum(v) if v else None, 9), fmt(1/(math.exp(2*math.pi*mh) + 1), 9)] for mh, v in zip((0.25, 0.5, 1.0), dsv)],
            widths=[0.2, 0.4, 0.4])
    d.p('The integrator is also checked on the Landau–Zener problem $i\\,dc/dt=(\\kappa\\sigma_1+t\\sigma_3)c$, $t$ from $-150$ to $150$, '
        'whose exact result is $|\\beta|^2=e^{-\\pi\\kappa^2}$.')

    # ==============================================================================================
    d.h1('8. Verification')
    d.p('Every statement above is a check of 7+1.nb (Wolfram Language 15.0.1) and of the independent Python program '
        'tools/ref_gravity.py (sympy, numpy, scipy), which rebuilds the Dirac matrices from 4+4.nb’s split octonions and computes '
        'everything again with its own curvature and Lovelock engine (tools/lovelock71.py). The checks of sections 11–14 of the notebook:')
    d.table(['#', 'check', 'result', 'section'],
            [[str(i + 1), '`' + c[0].replace('`', "'") + '`', c[1], c[3][:4] if c[3] else c[2][:3]] for i, c in enumerate(ck)],
            widths=[0.06, 0.74, 0.08, 0.12], small=True)
    d.p('The Python program’s boolean checks:')
    d.table(['#', 'check', 'result'],
            [[str(i + 1), '`' + k.replace('`', "'") + '`', v] for i, (k, v) in enumerate([(k, v) for k, v in ref.items() if v in ('True', 'False')])],
            widths=[0.06, 0.82, 0.12], small=True)
    d.h1('9. How to reproduce')
    d.ol(['`python3 tools/make_7p1_nb.py` writes 7+1.nb (unevaluated) from tools/make_7p1_nb.py and tools/nb_part_*.py.',
          'Evaluate 7+1.nb in a fresh kernel of Wolfram 15.0.1 (Evaluation ▸ Quit Kernel, then Evaluation ▸ Evaluate Notebook; or `Get["D:/Developer/github/7+1/tools/run_eval.wl"]`) and save it; the last section summarizes all checks.',
          '`python3 tools/ref_gravity.py` repeats the checks of this document independently (exit code 0 if all pass).',
          '`python3 tools/make_docs.py` regenerates this document, its symbol dictionary and its provenance record.'])
