def _pylist(s):
    import re
    vals = re.findall(r'(-?\d+\.\d+(?:e-?\d+)?)', s or '')
    return [float(v) for v in vals] if vals else None

def _frac_tex(v):
    import re
    m = re.fullmatch(r'\s*(-?\d+)\s*/\s*(\d+)\s*', re.sub(r'[()\s]', '', v or ''))
    if not m: return v or '?'
    n, dd = int(m.group(1)), int(m.group(2))
    if max(len(str(abs(n))), len(str(dd))) > 15:
        return r'q\approx %s,\\ q\in\mathbb Q\ \text{(an exact fraction: numerator of %d, denominator of %d digits)}' % (
            fmt(n/dd, 12), len(str(abs(n))), len(str(dd)))
    return r'\tfrac{%d}{%d}\approx %s' % (n, dd, fmt(n/dd, 10))

def _tex_num(x):
    import sympy as sp
    try:
        return sp.latex(sp.nsimplify(x))
    except Exception:
        return str(x)

def _ratio_tex(ex, key):
    """(A w1 - B Lambda)/den for the solution w2 or w3 of the exponential vacuum equations, with A, B, den polynomials in qH"""
    import sympy as sp
    sol = ex.get('sol') or {}
    k = [v for kk, v in sol.items() if str(kk) == key]
    if not k: return '?'
    w1, Lam, qH = sp.symbols('w_1 Lambda q_H')
    num, den = sp.fraction(sp.together(k[0]))
    num = sp.expand(num)
    A, B = num.coeff(w1), -num.coeff(Lam)
    if sp.Poly(A, qH).LC() < 0:
        A, B, den = -A, -B, -den
    return r'\frac{\big(%s\big)\,w_1-\big(%s\big)\,\Lambda}{%s}' % (sp.latex(sp.expand(A)), sp.latex(sp.expand(B)), sp.latex(sp.factor(den)))
